"use client";

import Image from "next/image";
import { useEffect, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { trackShare } from "@/lib/analytics";

const highlights = [
  {
    eyebrow: "CASEFLOW COMMAND",
    title: "A clearer command center for case management.",
    description:
      "Caseload, documentation, compliance, analytics, and follow-up workflows brought into one focused operating system.",
    image: "data:image/webp;base64,",
    accent: "from-cyan-400 to-emerald-400",
  },
  {
    eyebrow: "CAREPORT CONNECT",
    title: "Service coordination built around people.",
    description:
      "A connected operations hub that helps teams act on needs, protect continuity, and keep essential support moving.",
    image: "data:image/webp;base64,",
    accent: "from-indigo-400 to-cyan-400",
  },
  {
    eyebrow: "CONNECTED WORKSPACE",
    title: "Communication belongs inside the workflow.",
    description:
      "Messaging, intelligent assistance, and team coordination live alongside the work instead of becoming another disconnected tool.",
    image: "data:image/webp;base64,",
    accent: "from-violet-400 to-sky-400",
  },
  {
    eyebrow: "T.O.O.L.S. INC.",
    title: "A practical path forward after incarceration.",
    description:
      "Reentry technology connecting education, employment readiness, mentorship, resources, and long-term stability.",
    image: "/logos/tools.webp",
    accent: "from-emerald-400 to-green-300",
    contain: true,
  },
  {
    eyebrow: "A MACKPROJEKT",
    title: "Ideas. Innovation. Solutions.",
    description:
      "Founder-led technology designed for access, opportunity, trust, and the communities too often left outside the system.",
    image: "/logos/amp-logo.jpeg",
    accent: "from-green-400 via-cyan-400 to-violet-400",
    contain: true,
  },
];

const SLIDE_DURATION = 6500;

export function LaunchHighlights() {
  const [active, setActive] = useState(0);
  const [playing, setPlaying] = useState(true);

  useEffect(() => {
    if (!playing) return;
    const timer = window.setInterval(
      () => setActive((current) => (current + 1) % highlights.length),
      SLIDE_DURATION,
    );
    return () => window.clearInterval(timer);
  }, [playing]);

  const goTo = (index: number) => {
    setActive((index + highlights.length) % highlights.length);
  };

  const share = async () => {
    const url = window.location.href;
    trackShare("native", "launch-highlights");
    if (navigator.share) {
      try {
        await navigator.share({
          title: "A MackProjekt — Building What Matters",
          text: "See the technology A MackProjekt is building to move people forward.",
          url,
        });
        return;
      } catch {
        return;
      }
    }
    await navigator.clipboard.writeText(url);
  };

  const slide = highlights[active];

  return (
    <motion.div
      initial={{ opacity: 0, y: 24 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.65 }}
      className="relative w-full"
    >
      <div className="relative overflow-hidden rounded-2xl border-2 border-green-400/30 bg-[#05070b] shadow-[0_0_40px_rgba(34,197,94,0.24),0_0_90px_rgba(56,189,248,0.14)]">
        <div className="pointer-events-none absolute inset-0 z-20 bg-gradient-to-r from-green-400/10 via-transparent to-cyan-400/10" />
        <div className="pointer-events-none absolute left-4 top-4 z-30 h-12 w-12 rounded-tl-xl border-l-2 border-t-2 border-green-400" />
        <div className="pointer-events-none absolute right-4 top-4 z-30 h-12 w-12 rounded-tr-xl border-r-2 border-t-2 border-cyan-400" />

        <div className="relative aspect-video">
          <AnimatePresence mode="wait">
            <motion.div
              key={slide.title}
              initial={{ opacity: 0, scale: 1.025 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.985 }}
              transition={{ duration: 0.55, ease: "easeOut" }}
              className="absolute inset-0"
            >
              <Image
                src={slide.image}
                alt={`${slide.eyebrow} project snapshot`}
                fill
                priority={active === 0}
                sizes="(max-width: 1200px) 100vw, 1140px"
                className={slide.contain ? "object-contain p-16" : "object-cover"}
              />
              <div className="absolute inset-0 bg-gradient-to-t from-[#05070b] via-[#05070b]/35 to-transparent" />
              <div className="absolute inset-x-0 bottom-0 p-6 sm:p-9 lg:p-12">
                <p className={`bg-gradient-to-r ${slide.accent} bg-clip-text text-xs font-extrabold tracking-[0.28em] text-transparent sm:text-sm`}>
                  {slide.eyebrow}
                </p>
                <h3 className="mt-3 max-w-4xl text-2xl font-extrabold leading-tight text-white sm:text-4xl lg:text-5xl">
                  {slide.title}
                </h3>
                <p className="mt-3 max-w-3xl text-sm leading-relaxed text-white/75 sm:text-base lg:text-lg">
                  {slide.description}
                </p>
              </div>
            </motion.div>
          </AnimatePresence>

          <button
            type="button"
            onClick={() => goTo(active - 1)}
            aria-label="Previous highlight"
            className="absolute left-4 top-1/2 z-40 -translate-y-1/2 rounded-full border border-white/20 bg-black/45 px-4 py-3 text-xl text-white backdrop-blur transition hover:border-green-400 hover:bg-black/70"
          >
            ←
          </button>
          <button
            type="button"
            onClick={() => goTo(active + 1)}
            aria-label="Next highlight"
            className="absolute right-4 top-1/2 z-40 -translate-y-1/2 rounded-full border border-white/20 bg-black/45 px-4 py-3 text-xl text-white backdrop-blur transition hover:border-cyan-400 hover:bg-black/70"
          >
            →
          </button>
        </div>

        <div className="relative z-40 flex flex-wrap items-center justify-between gap-4 border-t border-white/10 bg-black/60 px-5 py-4 backdrop-blur">
          <div className="flex flex-1 gap-2" aria-label="Highlight progress">
            {highlights.map((item, index) => (
              <button
                key={item.eyebrow}
                type="button"
                onClick={() => goTo(index)}
                aria-label={`Show ${item.eyebrow}`}
                className="group h-2 min-w-8 flex-1 overflow-hidden rounded-full bg-white/15"
              >
                <span
                  className={`block h-full rounded-full bg-gradient-to-r ${item.accent} transition-all duration-300 ${index === active ? "w-full" : "w-0 group-hover:w-1/3"}`}
                />
              </button>
            ))}
          </div>
          <button
            type="button"
            onClick={() => setPlaying((value) => !value)}
            className="rounded-lg border border-white/15 px-4 py-2 text-xs font-bold uppercase tracking-wider text-white/80 transition hover:border-green-400 hover:text-white"
          >
            {playing ? "Pause" : "Play"}
          </button>
          <button
            type="button"
            onClick={share}
            className="rounded-lg bg-gradient-to-r from-green-400 to-cyan-400 px-4 py-2 text-xs font-extrabold uppercase tracking-wider text-[#05070b] transition hover:brightness-110"
          >
            Share
          </button>
        </div>
      </div>

      <p className="mt-5 text-sm font-semibold uppercase tracking-[0.2em] text-muted">
        Highlight {String(active + 1).padStart(2, "0")} / {String(highlights.length).padStart(2, "0")}
      </p>
    </motion.div>
  );
}
